let particles = [];
let numParticles = 100;
let particleSize = 3;
let umidade = 0; // Current wetness level

function Particle(x, y) {
    this.x = x;
    this.y = y;
    this.vx = (Math.random() - 0.5) * 0.1; // Small initial velocity
    this.vy = (Math.random() - 0.5) * 0.1;
    this.initialX = x; // Store initial position for solid state
    this.initialY = y;
    this.color = 'rgba(150, 75, 0, 1)';
}

Particle.prototype.draw = function() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, particleSize, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
};

Particle.prototype.update = function() {
    const solidness = 1 - umidade; // 1 for solid, 0 for soft

    this.vx += (Math.random() - 0.5) * (umidade * 0.5);
    this.vy += (Math.random() - 0.5) * (umidade * 0.5);

    this.x += this.vx;
    this.y += this.vy;

    // Boundary check
    if (this.x < 0 || this.x > canvas.width) this.vx *= -1;
    if (this.y < 0 || this.y > canvas.height) this.vy *= -1;

    // Gently pull towards initial position in solid state
    if (solidness > 0.1) {
        const attractionFactor = solidness * 0.01;
        this.vx += (this.initialX - this.x) * attractionFactor;
        this.vy += (this.initialY - this.y) * attractionFactor;
    }

    // Limit velocity
    const maxVel = 2 * umidade + 0.5;
    this.vx = Math.min(Math.max(this.vx, -maxVel), maxVel);
    this.vy = Math.min(Math.max(this.vy, -maxVel), maxVel);

    // Update color based on umidade
    const r = Math.round(150 + 50 * umidade);
    const g = Math.round(75 + 75 * umidade);
    const b = Math.round(0 + 100 * umidade);
    const a = 1 - (umidade * 0.5);
    this.color = `rgba(${r}, ${g}, ${b}, ${a})`;
};


function initParticles() {
    particles = [];
    const gridX = Math.ceil(Math.sqrt(numParticles));
    const gridY = Math.ceil(numParticles / gridX);
    const spacingX = canvas.width / (gridX + 1);
    const spacingY = canvas.height / (gridY + 1);

    for (let i = 0; i < numParticles; i++) {
        const col = i % gridX;
        const row = Math.floor(i / gridX);
        const x = (col + 1) * spacingX;
        const y = (row + 1) * spacingY;
        particles.push(new Particle(x, y));
    }
}

function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height); // Clear canvas

    // Draw background
    ctx.fillStyle = `rgba(240, 230, 210, ${1 - umidade * 0.5})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);


    for (let i = 0; i < particles.length; i++) {
        particles[i].update();
        particles[i].draw();
        for (let j = i + 1; j < particles.length; j++) {
            const dx = particles[i].x - particles[j].x;
            const dy = particles[i].y - particles[j].y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            const maxBondDistance = 40 * (1 + umidade); 
            if (distance < maxBondDistance) {
                const bondStrength = 1 - (distance / maxBondDistance);
                ctx.beginPath();
                ctx.moveTo(particles[i].x, particles[i].y);
                ctx.lineTo(particles[j].x, particles[j].y);
                ctx.strokeStyle = `rgba(100, 50, 0, ${bondStrength * (1 - umidade)})`;
                ctx.lineWidth = 1 * (1 - umidade); 
                ctx.stroke();
            }
        }
    }

    requestAnimationFrame(animate);
}

window.addEventListener('sim-state-change', (e) => {
    const state = e.detail;
    if (state.umidade !== undefined) {
        umidade = state.umidade;
    }
});

if (canvas && ctx) {
    initParticles();
    animate();
}
"},{"id":"markdown-3","type":"markdown","title":"A Física da Bolacha Molhada","content":"### A Transformação da Bolacha: Sólida para Macia

Uma bolacha crocante é um sólido devido às fortes interações entre suas moléculas (amido, açúcar, etc.), que as mantêm em uma estrutura relativamente rígida.

Quando a bolacha é exposta à umidade (água), as moléculas de água penetram nessa estrutura. A água é uma molécula polar e é muito eficaz em formar ligações de hidrogênio e interagir com outras moléculas polares na bolacha.

Essas interações com a água começam a **interromper as forças intermoleculares** que mantinham a estrutura sólida da bolacha. As ligações entre as moléculas da bolacha enfraquecem, permitindo que elas se movam com mais liberdade.

Visualmente, isso se manifesta como a bolacha perdendo sua rigidez e tornando-se "mole" ou "pastosa". As partículas na simulação representam essas moléculas ou aglomerados de moléculas, e você pode observar como a umidade aumenta sua mobilidade e reduz a coesão entre elas.

**Interações moleculares:**
*   **Forças em seco:** As moléculas da bolacha possuem ligações fortes, mantendo-as próximas e em posições fixas.
*   **Com umidade:** As moléculas de água agem como um "lubrificante" e um agente "separador", enfraquecendo as ligações e permitindo maior movimento e menor rigidez estrutural.
