function drawSimulation() {
  if (!ctx || !canvas) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const centerX = canvas.width / 2;
  const centerY = canvas.height / 2;

  // Atom 1 position
  const atom1X = centerX - distance / 2;
  const atom1Y = centerY;

  // Atom 2 position
  const atom2X = centerX + distance / 2;
  const atom2Y = centerY;

  // Draw Atom 1 (Blue)
  ctx.beginPath();
  ctx.arc(atom1X, atom1Y, atomSize, 0, Math.PI * 2);
  ctx.fillStyle = '#2196F3'; // Blue
  ctx.fill();
  ctx.strokeStyle = '#1976D2';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw Electron Cloud for Atom 1
  ctx.beginPath();
  ctx.arc(atom1X, atom1Y, atomSize * 1.5, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(33, 150, 243, 0.2)'; // Light blue translucent
  ctx.fill();

  // Draw Atom 2 (Red)
  ctx.beginPath();
  ctx.arc(atom2X, atom2Y, atomSize, 0, Math.PI * 2);
  ctx.fillStyle = '#F44336'; // Red
  ctx.fill();
  ctx.strokeStyle = '#D32F2F';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw Electron Cloud for Atom 2
  ctx.beginPath();
  ctx.arc(atom2X, atom2Y, atomSize * 1.5, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(244, 67, 54, 0.2)'; // Light red translucent
  ctx.fill();

  // Optional: Visual cue for repulsion when close
  if (distance < atomSize * 2.5) { // When electron clouds start to overlap significantly
    ctx.strokeStyle = '#FFC107'; // Amber
    ctx.lineWidth = 3;

    // Repulsion lines/arrows
    ctx.beginPath();
    ctx.moveTo(atom1X + atomSize, atom1Y);
    ctx.lineTo(atom1X + atomSize + 10, atom1Y);
    ctx.moveTo(atom2X - atomSize, atom2Y);
    ctx.lineTo(atom2X - atomSize - 10, atom2Y);
    ctx.stroke();

    // Arrowheads
    ctx.beginPath();
    ctx.moveTo(atom1X + atomSize + 10, atom1Y);
    ctx.lineTo(atom1X + atomSize + 5, atom1Y - 5);
    ctx.moveTo(atom1X + atomSize + 10, atom1Y);
    ctx.lineTo(atom1X + atomSize + 5, atom1Y + 5);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(atom2X - atomSize - 10, atom2Y);
    ctx.lineTo(atom2X - atomSize - 5, atom2Y - 5);
    ctx.moveTo(atom2X - atomSize - 10, atom2Y);
    ctx.lineTo(atom2X - atomSize - 5, atom2Y + 5);
    ctx.stroke();
